export function render(container: HTMLElement) {
  const app = document.createElement('div');
  app.className = 'app';
  app.style.maxWidth = '960px';
  app.style.margin = '0 auto';
  app.style.padding = '24px';

  const title = document.createElement('h1');
  title.textContent = 'Temp Converter';
  title.style.color = '#333333';
  title.style.fontSize = '2rem';
  title.style.marginBottom = '16px';

  const card = document.createElement('div');
  card.className = 'card';
  card.style.background = '#15152a';
  card.style.border = '1px solid rgba(255,255,255,0.1)';
  card.style.borderRadius = '12px';
  card.style.padding = '16px';
  card.style.marginBottom = '16px';

  const input = document.createElement('input');
  input.id = 'tempInput';
  input.type = 'number';
  input.min = '-459.67';
  input.placeholder = 'Enter temperature';
  input.style.width = '100%';
  input.style.padding = '8px';
  input.style.border = '1px solid #ccc';
  input.style.borderRadius = '4px';
  input.style.marginBottom = '8px';

  const fromUnit = document.createElement('select');
  fromUnit.id = 'fromUnit';
  fromUnit.style.width = '100%';
  fromUnit.style.padding = '8px';
  fromUnit.style.border = '1px solid #ccc';
  fromUnit.style.borderRadius = '4px';
  fromUnit.style.marginBottom = '8px';
  const units = ['Celsius', 'Fahrenheit', 'Kelvin'];
  units.forEach(unit => {
    const option = document.createElement('option');
    option.value = unit;
    option.textContent = unit;
    fromUnit.appendChild(option);
  });

  const toUnit = document.createElement('select');
  toUnit.id = 'toUnit';
  toUnit.style.width = '100%';
  toUnit.style.padding = '8px';
  toUnit.style.border = '1px solid #ccc';
  toUnit.style.borderRadius = '4px';
  toUnit.style.marginBottom = '8px';
  units.forEach(unit => {
    const option = document.createElement('option');
    option.value = unit;
    option.textContent = unit;
    toUnit.appendChild(option);
  });

  const result = document.createElement('div');
  result.id = 'result';
  result.style.fontSize = '1.2rem';
  result.style.color = '#4ade80';
  result.style.marginTop = '8px';

  card.appendChild(input);
  card.appendChild(fromUnit);
  card.appendChild(toUnit);
  card.appendChild(result);

  const convertCtoF = () => {
    const value = parseFloat(input.value);
    const converted = convertTemperature(value, 'Celsius', 'Fahrenheit');
    result.textContent = `${value}°C is ${converted}°F`;
  };
  const convertCtoK = () => {
    const value = parseFloat(input.value);
    const converted = convertTemperature(value, 'Celsius', 'Kelvin');
    result.textContent = `${value}°C is ${converted}K`;
  };
  const convertFtoC = () => {
    const value = parseFloat(input.value);
    const converted = convertTemperature(value, 'Fahrenheit', 'Celsius');
    result.textContent = `${value}°F is ${converted}°C`;
  };
  const convertFtoK = () => {
    const value = parseFloat(input.value);
    const converted = convertTemperature(value, 'Fahrenheit', 'Kelvin');
    result.textContent = `${value}°F is ${converted}K`;
  };
  const convertKtoC = () => {
    const value = parseFloat(input.value);
    const converted = convertTemperature(value, 'Kelvin', 'Celsius');
    result.textContent = `${value}K is ${converted}°C`;
  };
  const convertKtoF = () => {
    const value = parseFloat(input.value);
    const converted = convertTemperature(value, 'Kelvin', 'Fahrenheit');
    result.textContent = `${value}K is ${converted}°F`;
  };

  const buttons = [
    { label: 'Celsius to Fahrenheit', onClick: convertCtoF },
    { label: 'Celsius to Kelvin', onClick: convertCtoK },
    { label: 'Fahrenheit to Celsius', onClick: convertFtoC },
    { label: 'Fahrenheit to Kelvin', onClick: convertFtoK },
    { label: 'Kelvin to Celsius', onClick: convertKtoC },
    { label: 'Kelvin to Fahrenheit', onClick: convertKtoF }
  ];
  buttons.forEach(btn => {
    const button = document.createElement('button');
    button.className = 'btn';
    button.textContent = btn.label;
    button.onclick = btn.onClick;
    card.appendChild(button);
  });

  app.appendChild(title);
  app.appendChild(card);
  container.appendChild(app);
}

