}

export function handleInput(value: number, fromUnit: 'Celsius' | 'Fahrenheit' | 'Kelvin', toUnit: 'Celsius' | 'Fahrenheit' | 'Kelvin'): ConversionResult {
  const convertedValue = convertTemperature(value, fromUnit, toUnit);
